@@ -35,6 +35,48 @@
         background: rgba(255, 255, 255, 0.72);
         border: 1px solid var(--ut-line);
       }
+      /* Desktop: row height comes from Detail+Ask; Findings fills and scrolls. */
+      @media (min-width: 992px) {
+        .ut-workspace {
+          display: grid;
+          grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
+          gap: 1.5rem;
+          align-items: stretch;
+        }
+        .ut-workspace > [class*="col-"] {
+          width: auto;
+          max-width: none;
+          flex: none;
+          padding-left: 0;
+          padding-right: 0;
+        }
+        .ut-findings-col {
+          /* Do not let Findings content grow the row; match right column height. */
+          height: 0;
+          min-height: 100%;
+          display: flex;
+          flex-direction: column;
+          min-width: 0;
+        }
+        .ut-findings-panel {
+          flex: 1 1 auto;
+          min-height: 0;
+          overflow: hidden;
+        }
+        .ut-findings-scroll {
+          flex: 1 1 auto;
+          min-height: 0;
+          overflow-y: auto;
+          overscroll-behavior: contain;
+        }
+      }
+      @media (max-width: 991.98px) {
+        .ut-findings-scroll {
+          max-height: 40vh;
+          overflow-y: auto;
+          overscroll-behavior: contain;
+        }
+      }
       #advisoryOut {
         white-space: pre-wrap;
       }
